from PIL import Image
def runs(f,x=450,lo=100):
    im=Image.open(f).convert('RGB'); px=im.load(); W,H=im.size
    out=[];start=lo;cur=px[x,lo]
    for y in range(lo+1,H):
        c=px[x,y]
        if c!=cur:
            if y-start>=3: out.append((start,y-1,c))
            start=y;cur=c
    if H-start>=3: out.append((start,H-1,cur))
    return out
a=runs('r055-b3-0013.png'); b=runs('r057-dark2-0017.png')
print('R055 n=%d R057 n=%d'%(len(a),len(b)))
# align by color sequence
ai=[r[2] for r in a]; bi=[r[2] for r in b]
i=j=0
while i<len(ai) and j<len(bi):
    if ai[i]==bi[j]:
        print(f"  R055 {a[i][0]:4d}..{a[i][1]:4d}  vs  R057 {b[j][0]:4d}..{b[j][1]:4d}  dy={b[j][0]-a[i][0]:+3d}  {ai[i]}")
        i+=1;j+=1
    else:
        print(f"  --  R055 only {a[i]} | R057 only {b[j]}"); i+=1;j+=1
while i<len(ai): print('  --  R055 only',a[i]); i+=1
while j<len(bi): print('  --  R057 only',b[j]); j+=1
